# Instalador de la web publica de Chivato Ofertas (estilo buscador de chollos, caramelo).
# No toca bot.py. Sustituye /opt/chivato/codigos/web.html, que sirve el servicio chivato-codigos en /web.
import base64, os, re, shutil, subprocess, sys, time, urllib.request

DIR = "/opt/chivato/codigos"
DEST = os.path.join(DIR, "web.html")
CADDY = "/etc/caddy/Caddyfile"
HOST = "chivato-ofertas.duckdns.org"
WEB = ""

def sh(cmd):
    return subprocess.run(cmd, shell=True, capture_output=True, text=True)

sello = time.strftime("%Y%m%d-%H%M%S")
print("== 1/3 Pagina")
if not os.path.isdir(DIR):
    print("ERROR: no existe %s (falta instalar Codigos). No toco nada." % DIR); sys.exit(1)
if os.path.exists(DEST):
    shutil.copy(DEST, DEST + ".bak-" + sello); print("copia de la anterior:", DEST + ".bak-" + sello)
open(DEST, "wb").write(base64.b64decode(WEB))
print("ok:", DEST)

print("== 2/3 Caddy")
caddy = open(CADDY, encoding="utf-8").read()
if "/web* 127.0.0.1:8766" in caddy:
    print("ya estaba")
else:
    m = re.search(r"^[^\n#]*" + re.escape(HOST) + r"[^\n]*\{[ \t]*\n", caddy, re.M)
    if not m:
        print("ERROR: no encuentro el bloque de %s en Caddy." % HOST); sys.exit(1)
    shutil.copy(CADDY, CADDY + ".bak-" + sello)
    open(CADDY, "w", encoding="utf-8").write(caddy[:m.end()] + "    reverse_proxy /web* 127.0.0.1:8766\n" + caddy[m.end():])
    if sh("caddy validate --config %s --adapter caddyfile" % CADDY).returncode != 0:
        shutil.copy(CADDY + ".bak-" + sello, CADDY); print("ERROR: Caddy no acepta el cambio, deshecho."); sys.exit(1)
    sh("systemctl reload caddy"); print("ok")

print("== 3/3 Comprobacion")
ok = True
for url in ("https://%s/web" % HOST, "https://%s/api/ofertas" % HOST, "https://%s/api/codigos" % HOST):
    try:
        r = urllib.request.urlopen(url, timeout=15).read()
        extra = " (web nueva)" if url.endswith("/web") and b"nadie te cuenta" in r else ""
        print("OK   ", url, len(r), "bytes" + extra)
    except Exception as e:
        ok = False; print("FALLA", url, e)
print("\nLISTO: abre https://%s/web" % HOST if ok else "\nHAY ALGUN FALLO: manda captura")
print("Para volver a la anterior: cp %s.bak-%s %s" % (DEST, sello, DEST))
